1import { useState, useMemo, useCallback } from "react";
2import Header from "./components/Header";
3import EntryCard from "./components/EntryCard";
4import Drawer from "./components/Drawer";
5import useFetch from "./hooks/useFetch";
6import useSearch from "./hooks/useSearch";
7
8const ENTRIES_PER_PAGE = 5;
9
10function App() {
11
12  const { data, isLoading, error, refetch } = useFetch(
13    "https://api.programiz.pro/api/Demo/v1/journal-entries"
14  );
15
16  const [selectedEntry, setSelectedEntry] = useState(null);
17  const [currentPage, setCurrentPage] = useState(1);
18
19  const entries = useMemo(function () {
20    if (!data) return [];
21
22    return data.map(function (post) {
23      return {
24        ...post,
25        date: new Date(post.date).toLocaleDateString("en-US", {
26          year: "numeric", month: "short", day: "numeric"
27        }).toUpperCase()
28      };
29    });
30  }, [data]);
31
32  const { query, setQuery, filteredEntries } = useSearch(entries);
33
34  const totalPages = useMemo(function () {
35    return Math.ceil(filteredEntries.length / ENTRIES_PER_PAGE);
36  }, [filteredEntries]);
37
38  const pagedEntries = useMemo(function () {
39    const start = (currentPage - 1) * ENTRIES_PER_PAGE;
40    return filteredEntries.slice(start, start + ENTRIES_PER_PAGE);
41  }, [filteredEntries, currentPage]);
42
43  const handleSelectEntry = useCallback(function (entry) {
44    setSelectedEntry(entry);
45  }, []);
46
47  const handleCloseDrawer = useCallback(function () {
48    setSelectedEntry(null);
49  }, []);
50
51  function handleQueryChange(newQuery) {
52    setQuery(newQuery);
53    setCurrentPage(1);
54  }
55
56  function handleNext() {
57    setCurrentPage(function (p) { return Math.min(p + 1, totalPages); });
58  }
59
60  function handlePrev() {
61    setCurrentPage(function (p) { return Math.max(p - 1, 1); });
62  }
63
64  return (
65    <div className="main-container">
66      <Header query={query} onQueryChange={handleQueryChange} />
67
68      <section className="entries-section">
69        <div className="entry-list-header">
70          <h3>Recent Entries</h3>
71          <span className="entry-count">{filteredEntries.length}</span>
72          {query && <span className="entry-count">{"of " + entries.length}</span>}
73
74          <button className="btn btn-secondary" onClick={refetch}>Refresh</button>
75
76        </div>
77
78        {isLoading ? (
79          <p className="loading-state">Loading entries...</p>
80        ) : error ? (
81          <div className="error-banner">
82            <p className="error-label">Something went wrong.</p>
83            <p className="error-detail">{error}</p>
84          </div>
85        ) : pagedEntries.length === 0 ? (
86          <p className="empty-state">No entries found.</p>
87        ) : (
88          pagedEntries.map((entry) => (
89            <EntryCard
90              key={entry.id}
91              id={entry.id}
92              title={entry.title}
93              date={entry.date}
94              content={entry.content}
95              author={entry.author}
96              onSelect={handleSelectEntry}
97            />
98          ))
99        )}
100
101        {!isLoading && !error && totalPages > 1 && (
102          <div className="pagination">
103
104            <button className="btn btn-secondary" onClick={handlePrev} disabled={currentPage === 1}>Previous</button>
105
106            <span className="pagination-info">Page {currentPage} of {totalPages}</span>
107
108            <button className="btn btn-secondary" onClick={handleNext} disabled={currentPage === totalPages}>Next</button>
109          </div>
110        )}
111      </section>
112
113      <Drawer entry={selectedEntry} onClose={handleCloseDrawer} />
114
115    </div>
116  );
117}
118
119export default App;

